<?php
require_once __DIR__ . '/_bootstrap.php';
$id=(int)($_GET['id']??0); $shipment=$id?logisticsOne('SELECT * FROM shipments WHERE id=?',[$id]):null;
$events=$id?logisticsRows('SELECT * FROM shipment_tracking WHERE shipment_id=? ORDER BY created_at DESC',[$id]):[];
logisticsPage('Shipment details','shipments.php'); ?>
<?php if(!$shipment): ?><section class="lx-card"><div class="lx-empty">Shipment not found or shipment data is unavailable.<br><br><a class="lx-btn" href="shipments.php">Back to shipments</a></div></section><?php else: ?><div class="lx-detail"><section class="lx-card"><h2><?=e(logisticsValue($shipment,['tracking_number','tracking_code','reference']))?></h2><p><span class="lx-badge"><?=e(logisticsStatus(logisticsValue($shipment,['status'],'pending')))?></span></p><dl class="lx-meta"><?php foreach(['Carrier'=>['carrier','courier'],'Destination'=>['destination','delivery_address','city'],'Origin'=>['origin','pickup_address'],'Weight'=>['weight'],'Created'=>['created_at'],'Expected delivery'=>['estimated_delivery','delivery_date']] as $label=>$keys): ?><div><dt><?=e($label)?></dt><dd><?=e(logisticsValue($shipment,$keys))?></dd></div><?php endforeach; ?></dl><br><a class="lx-btn" href="tracking.php?tracking=<?=e(logisticsValue($shipment,['tracking_number','tracking_code'],' '))?>">Open live tracking</a></section><section class="lx-card"><h2>Tracking timeline</h2><?php if(!$events): ?><div class="lx-empty">No scan events have been recorded for this shipment.</div><?php else: ?><ul class="lx-timeline"><?php foreach($events as $event): ?><li><div><strong><?=e(logisticsStatus(logisticsValue($event,['status','event','title'],'Update')))?></strong><small><?=e(logisticsValue($event,['location','description']))?><br><?=e(logisticsValue($event,['created_at','event_time']))?></small></div></li><?php endforeach; ?></ul><?php endif; ?></section></div><?php endif; ?>
<?php logisticsEnd(); ?>
